'use strict';
(() => {
const ui=id=>document.getElementById(id), names=['knn','random_forest','naive_bayes','k_means','cnn'];
const labels={knn:'KNN',random_forest:'Random Forest',naive_bayes:'Naive Bayes',k_means:'K-means',cnn:'CNN 1D'};
const state={bundle:null,task:'potential',selectedId:null,candidates:[],lastPrediction:null,nasaRaw:null,boundary:null};
const safe=s=>String(s??'Não informado').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(n,d=1)=>Number(n).toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d});
const pct=n=>num(100*n,1)+'%';
function task(){return state.bundle.tasks[state.task];}
function dist(a,b){const rad=Math.PI/180,la1=a[0]*rad,la2=b[0]*rad,dl=(b[0]-a[0])*rad,dn=(b[1]-a[1])*rad;return 6371*2*Math.asin(Math.min(1,Math.sqrt(Math.sin(dl/2)**2+Math.cos(la1)*Math.cos(la2)*Math.sin(dn/2)**2)));}
function nearest(t,x){let record=null,distance=Infinity;for(const r of t.records){const d=dist(x,[r.latitude,r.longitude]);if(d<distance){distance=d;record=r;}}return {record,distance};}
function scale(t,x){return x.map((v,i)=>(v-t.scaler.mean[i])/t.scaler.scale[i]);}
function infer(t,name,raw){const x=scale(t,raw),m=t.models[name].parameters;let score;
 if(name==='random_forest'){const xf=x.map(Math.fround);score=m.trees.reduce((total,tr)=>{let n=0;while(tr.left[n]>=0)n=xf[tr.feature[n]]<=tr.threshold[n]?tr.left[n]:tr.right[n];return total+tr.p1[n];},0)/m.trees.length;}
 else if(name==='knn'){const close=m.x.map((row,i)=>({d:row.reduce((a,v,j)=>a+(v-x[j])**2,0),y:m.y[i],i})).sort((a,b)=>a.d-b.d||a.i-b.i).slice(0,m.k);score=close.reduce((a,b)=>a+b.y,0)/m.k;}
 else if(name==='naive_bayes'){const z=m.mean.map((row,k)=>Math.log(m.prior[k])-row.reduce((a,v,i)=>a+.5*(Math.log(2*Math.PI*m.variance[k][i])+(x[i]-v)**2/m.variance[k][i]),0));const top=Math.max(...z),p=z.map(a=>Math.exp(a-top));score=p[1]/(p[0]+p[1]);}
 else if(name==='k_means'){const d=m.centers.map(c=>c.reduce((a,v,i)=>a+(v-x[i])**2,0));const k=d[1]<d[0]?1:0;return {label:m.class_map[k],score:null,cluster:k};}
 else if(name==='cnn'){const h=[];for(let p=0;p<2;p++)for(let f=0;f<8;f++)h.push(Math.max(0,m.bc[f]+m.wc[f][0]*x[p]+m.wc[f][1]*x[p+1]));let z=m.bd.map((b,k)=>b+h.reduce((a,v,i)=>a+v*m.wd[i][k],0));let max=Math.max(...z);z=z.map(v=>Math.exp(v-max));score=z[1]/(z[0]+z[1]);}
 else throw Error('Método desconhecido.');
 return {label:score>.5?1:0,score};
}
function className(t,l){return t.task==='potential'?(l?'Evidência de produção':'Situação seco'):(l?'CE > 3 dS/m':'CE ≤ 3 dS/m');}
function inputs(){const x=['aiLat','aiLon','aiDepth'].map(id=>ui(id).valueAsNumber);if(!x.every(Number.isFinite)||x[2]<=0)throw Error('Informe coordenadas e profundidade válidas.');return x;}
function validatePoint(t,x){if(x.some((v,i)=>v<t.bounds.min[i]||v>t.bounds.max[i]))throw Error('Ponto ou profundidade fora do intervalo observado no treino.');if(state.boundary&&!insideBoundary(x))throw Error('O ponto está fora do contorno da Paraíba.');const n=nearest(t,x);if(n.distance>5)throw Error(`O cadastro usado pelo modelo está a ${num(n.distance,1)} km. Esta versão limita hipóteses a 5 km de uma observação.`);return n;}
function ringContains(p,ring){let inside=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const a=ring[i],b=ring[j];if((a[1]>p[1])!==(b[1]>p[1])&&p[0]<(b[0]-a[0])*(p[1]-a[1])/(b[1]-a[1])+a[0])inside=!inside;}return inside;}
function insideBoundary(x){const p=[x[1],x[0]], geometries=state.boundary.type==='FeatureCollection'?state.boundary.features.map(f=>f.geometry):[state.boundary.geometry||state.boundary];for(const g of geometries){const polys=g.type==='Polygon'?[g.coordinates]:g.type==='MultiPolygon'?g.coordinates:[];for(const poly of polys)if(ringContains(p,poly[0])&&!poly.slice(1).some(r=>ringContains(p,r)))return true;}return false;}
function message(s,error=false){ui('aiMessage').textContent=s;ui('aiMessage').className=error?'error':'small';}
function predict(x=inputs(),record=null){const t=task(),n=validatePoint(t,x);const heldout=record&&x.every((v,i)=>Math.abs(v-[record.latitude,record.longitude,record.depth_m][i])<1e-10);
 const predictions=Object.fromEntries(names.map(name=>[name,heldout?{label:record.oof[name],score:null}:infer(t,name,x)]));
 state.lastPrediction={task:state.task,input:x,predictions,mode:heldout?'out-of-fold':'full-training-fit',nearest_id:n.record.id,nearest_km:n.distance};
 ui('aiPrediction').innerHTML='<thead><tr><th>Método</th><th>Classe estimada</th><th>Escore do modelo</th></tr></thead><tbody>'+names.map(name=>`<tr><td>${labels[name]}</td><td>${className(t,predictions[name].label)}</td><td>${heldout?'Validação fora do treino':predictions[name].score===null?'Grupo '+(predictions[name].cluster+1):num(predictions[name].score,3)}</td></tr>`).join('')+'</tbody>';
 ui('aiRecordNote').textContent=heldout?`Registro ${record.id} • ${record.municipality}. Classe observada: ${className(t,record.label)}. Previsão do grupo de teste ${record.fold}, sem este grupo no treino.`:`Cenário em ${num(x[0],5)}°, ${num(x[1],5)}°, ${num(x[2],1)} m. Modelos ajustados com todos os registros. Observação mais próxima: ${n.record.id}, a ${num(n.distance,2)} km.`;
 message(heldout?'A classe observada vem do cadastro histórico. A previsão não é uma medição atual.':'Hipótese computacional. Não há confirmação de água, vazão ou potabilidade neste ponto.');drawMap(x);return state.lastPrediction;
}
function loadMunicipalities(){const t=task(),ms=[...new Set(t.records.map(r=>r.municipality))].sort((a,b)=>a.localeCompare(b,'pt-BR'));ui('aiMunicipality').innerHTML=ms.map(m=>`<option>${safe(m)}</option>`).join('');ui('aiMunicipality').value=ms.includes('Cabaceiras')?'Cabaceiras':ms[0];ui('aiMunicipality').disabled=false;loadWells();}
function loadWells(){const rows=task().records.filter(r=>r.municipality===ui('aiMunicipality').value);ui('aiWell').innerHTML=rows.map(r=>`<option value="${safe(r.id)}">${safe(r.id)} • ${num(r.depth_m,0)} m • ${className(task(),r.label)}</option>`).join('');ui('aiWell').disabled=false;selectWell();}
function selectWell(){const r=task().records.find(r=>r.id===ui('aiWell').value);if(!r)return;state.selectedId=r.id;ui('aiLat').value=r.latitude;ui('aiLon').value=r.longitude;ui('aiDepth').value=r.depth_m;state.candidates=[];ui('exportCandidates').disabled=true;ui('candidateTable').innerHTML='<tr><td>Use “Gerar hipóteses de locais” para explorar pontos próximos.</td></tr>';try{predict(inputs(),r);}catch(e){message(e.message,true);}}
function comparison(){const t=task(),base=t.baseline;ui('aiStats').innerHTML=[['Registros no treino',num(t.n,0),`${t.municipalities} municípios`],['Classe 0',num(t.class_counts[0],0),className(t,0)],['Classe 1',num(t.class_counts[1],0),className(t,1)]].map(v=>`<div class="metric"><div class="label">${v[0]}</div><div class="value">${v[1]}</div><div class="unit">${v[2]}</div></div>`).join('');
 ui('aiValidationNote').textContent=`Validação espacial: 5 grupos de teste, ${t.groups} células. Acurácia balanceada dá o mesmo peso às duas classes. Referência da classe mais frequente: ${pct(base.balanced_accuracy)} balanceada / ${pct(base.accuracy)} acurácia simples.`;
 const cls=t.task==='potential'?'secos':'CE > 3';ui('aiComparison').innerHTML=`<thead><tr><th>Método</th><th>Acurácia</th><th>Balanceada</th><th>F1 macro</th><th>Recall ${cls}</th></tr></thead><tbody>`+names.map(n=>{const m=t.models[n].metrics_oof;return `<tr><td>${labels[n]}</td><td>${pct(m.accuracy)}</td><td>${pct(m.balanced_accuracy)}</td><td>${num(m.macro_f1,3)}</td><td>${pct(t.task==='potential'?m.recall_class0:m.recall_class1)}</td></tr>`;}).join('')+'</tbody>';
 ui('aiProvenance').textContent=`Consulta SGB/SIAGAS em ${t.provenance.accessed||t.provenance.access_date||'04/10/2026'}. ${num(t.provenance.returned_count,0)} registros retornados; ${num(t.n,0)} usados nesta tarefa. ${t.task==='potential'?'24 registros secos com vazão específica positiva foram excluídos por contradição; nenhum resultado ausente virou zero.':'Condutividade e profundidade positivas; 8.234 registros com coordenadas dentro do recorte estadual amplo. CE é indicador de salinidade, não resultado de potabilidade.'}`;
 drawBenchmark();
}
function drawBenchmark(){if(!state.bundle)return;const el=ui('aiBenchmark'),w=el.clientWidth;if(!w)return;const h=230,dpr=window.devicePixelRatio||1;el.width=w*dpr;el.height=h*dpr;const c=el.getContext('2d');c.scale(dpr,dpr);c.clearRect(0,0,w,h);const l=125,r=60,cw=w-l-r;c.font='13px system-ui';c.strokeStyle='#dce6e0';for(const v of [0,.25,.5,.75,1]){const x=l+v*cw;c.beginPath();c.moveTo(x,18);c.lineTo(x,195);c.stroke();c.fillStyle='#576c69';c.textAlign='center';c.fillText(`${v*100}%`,x,220);}
 names.forEach((n,i)=>{const y=24+i*34,m=task().models[n].metrics_oof;c.fillStyle='#123d3a';c.textAlign='right';c.fillText(labels[n],l-12,y+15);c.fillStyle=n==='random_forest'?'#087f78':'#60a59b';c.fillRect(l,y,m.balanced_accuracy*cw,22);c.fillStyle='#123d3a';c.textAlign='left';c.fillText(pct(m.balanced_accuracy),l+m.balanced_accuracy*cw+7,y+15);});c.setLineDash([5,4]);c.strokeStyle='#bb733e';c.beginPath();c.moveTo(l+task().baseline.balanced_accuracy*cw,15);c.lineTo(l+task().baseline.balanced_accuracy*cw,200);c.stroke();}
function candidates(){if(state.task!=='potential')throw Error('Geração de locais usa a tarefa produção × seco. Selecione essa pergunta primeiro.');const t=task(),x=inputs();validatePoint(t,x);const radius=ui('aiRadius').valueAsNumber;if(!Number.isFinite(radius)||radius<.5||radius>10)throw Error('Use raio de 0,5 a 10 km.');const list=[];
 for(let i=-3;i<=3;i++)for(let j=-3;j<=3;j++){if(Math.hypot(i,j)>3||(!i&&!j))continue;const a=[x[0]+i*radius/3/111.2,x[1]+j*radius/3/(111.2*Math.cos(x[0]*Math.PI/180)),x[2]];try{const n=validatePoint(t,a);if(n.distance<.15)continue;const p=infer(t,'random_forest',a);list.push({latitude:a[0],longitude:a[1],depth_m:a[2],rf_score:p.score,predicted_class:p.label,nearest_well_id:n.record.id,nearest_km:n.distance});}catch(e){/* outside the declared training/geographic domain */}}
 list.sort((a,b)=>b.rf_score-a.rf_score||a.nearest_km-b.nearest_km);state.candidates=list;ui('exportCandidates').disabled=!list.length;
 ui('candidateTable').innerHTML=list.length?'<thead><tr><th>Ordem</th><th>Latitude</th><th>Longitude</th><th>Escore RF</th><th>Registro mais próximo</th><th>Ação</th></tr></thead><tbody>'+list.slice(0,10).map((a,i)=>`<tr><td>${i+1}</td><td>${num(a.latitude,5)}</td><td>${num(a.longitude,5)}</td><td>${num(a.rf_score,3)}</td><td>${num(a.nearest_km,2)} km</td><td><button class="candidate-use" data-index="${i}">Explorar</button></td></tr>`).join('')+'</tbody>':'<tr><td>Não surgiram candidatos dentro do domínio e afastados 150 m dos registros. Ajuste centro ou raio.</td></tr>';
 ui('candidateTable').querySelectorAll('.candidate-use').forEach(b=>b.addEventListener('click',()=>{const a=state.candidates[Number(b.dataset.index)];state.selectedId=null;ui('aiLat').value=a.latitude;ui('aiLon').value=a.longitude;ui('aiDepth').value=a.depth_m;predict();}));message(`${list.length} pontos candidatos na grade. O ranking serve para planejar verificação em campo; não é recomendação de perfuração.`);drawMap(x);return list;
}
function drawMap(x){if(!state.bundle)return;const radius=Math.max(3,Number(ui('aiRadius').value)||3),near=state.bundle.tasks.potential.records.filter(r=>dist(x,[r.latitude,r.longitude])<=radius*1.3);const w=700,h=310,l=35,r=25,t=25,b=30,sx=(w-l-r)/(2*radius*1.3),sy=(h-t-b)/(2*radius*1.3),xy=(a)=>[l+(radius*1.3+(a[1]-x[1])*111.2*Math.cos(x[0]*Math.PI/180))*sx,t+(radius*1.3-(a[0]-x[0])*111.2)*sy];let svg=`<svg viewBox="0 0 ${w} ${h}" xmlns="http://www.w3.org/2000/svg" aria-label="Registros históricos e hipóteses próximos ao ponto" role="img"><rect width="${w}" height="${h}" fill="#f3f6f0"/>`;
 for(let i=-2;i<=2;i++){const k=i*radius/2,xx=l+(radius*1.3+k)*sx,yy=t+(radius*1.3-k)*sy;svg+=`<path d="M${xx} ${t}V${h-b}M${l} ${yy}H${w-r}" stroke="#dce6e0"/><text x="${xx}" y="${h-8}" text-anchor="middle" font-size="11" fill="#576c69">${num(k,1)} km E</text>`;}
 for(const a of near){const [cx,cy]=xy([a.latitude,a.longitude]);svg+=`<circle cx="${cx}" cy="${cy}" r="4" fill="${a.label?'#087f78':'#bb733e'}" opacity=".75"><title>${safe(a.id)}: ${a.label?'vazão específica positiva':'situação seco'}</title></circle>`;}
 state.candidates.slice(0,10).forEach((a,i)=>{const [cx,cy]=xy([a.latitude,a.longitude]);svg+=`<circle cx="${cx}" cy="${cy}" r="7" fill="#3368b2" stroke="white"/><text x="${cx+10}" y="${cy+4}" font-size="12" fill="#244b80">${i+1}</text>`;});const [cx,cy]=xy(x);svg+=`<path d="M${cx-7} ${cy}h14M${cx} ${cy-7}v14" stroke="#123d3a" stroke-width="2"/><text x="${w-18}" y="18" text-anchor="end" font-size="12" fill="#576c69">N ↑ • centro informado</text></svg>`;ui('aiMap').innerHTML=svg;
}
function download(filename,content,mime){const u=URL.createObjectURL(new Blob([content],{type:mime})),a=document.createElement('a');a.href=u;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function parseNASA(raw){const p=raw?.properties?.parameter,meta=raw?.parameters;if(!p||!meta)throw Error('Resposta NASA sem parâmetros esperados.');const units={PRECTOTCORR:'mm/day',T2M:'C',ALLSKY_SFC_SW_DWN:'MJ/m^2/day'};for(const [k,u] of Object.entries(units))if(meta[k]?.units!==u)throw Error('Unidade NASA inesperada para '+k+'.');const rows=[];for(let ms=Date.UTC(2024,0,1);ms<=Date.UTC(2025,11,31);ms+=86400000){const date=new Date(ms).toISOString().slice(0,10),key=date.replaceAll('-',''),v=[p.PRECTOTCORR[key],p.T2M[key],p.ALLSKY_SFC_SW_DWN[key]];if(v.some(n=>typeof n!=='number'||!Number.isFinite(n)||n===-999)||v[0]<0||v[2]<0)throw Error('Série NASA incompleta ou com valores inválidos.');rows.push({date,rain:v[0],temp:v[1],solar:v[2]});}return rows;}
async function fetchNASA(){const x=inputs();validatePoint(task(),x);const btn=ui('aiNASA');btn.disabled=true;const note=ui('nasaLiveMessage');note.className='small';note.textContent='Consultando a série diária NASA POWER…';const q=new URLSearchParams({parameters:'PRECTOTCORR,T2M,ALLSKY_SFC_SW_DWN',community:'AG',longitude:String(x[1]),latitude:String(x[0]),start:'20240101',end:'20251231',format:'JSON','time-standard':'UTC'}),url='https://power.larc.nasa.gov/api/temporal/daily/point?'+q,controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),45000);
 try{const res=await fetch(url,{signal:controller.signal});if(!res.ok)throw Error('NASA respondeu HTTP '+res.status);const raw=await res.json(),rows=parseNASA(raw);const source={provider:'NASA POWER',query_url:url,latitude:x[0],longitude:x[1],start:'2024-01-01',end:'2025-12-31',time_standard:'UTC',accessed:new Date().toISOString(),header:raw.header,units:raw.parameters};window.AguaTwin.setClimate(rows,source);state.nasaRaw={provenance:source,data:raw};ui('nasaLiveExport').disabled=false;note.textContent=`731 dias carregados em ${num(x[0],5)}°, ${num(x[1],5)}°. Chuva total de 2025: ${num(rows.filter(r=>r.date.startsWith('2025')).reduce((a,r)=>a+r.rain,0),1)} mm. O cenário de água e energia usa agora este ponto.`;return {days:rows.length,latitude:x[0],longitude:x[1]};}
 catch(e){note.className='error';note.textContent=(e.name==='AbortError'?'Consulta excedeu 45 segundos.':e.message)+ ' O cenário conserva a última série válida.';throw e;}finally{clearTimeout(timeout);btn.disabled=false;}
}
function attachWebMCP(){const context=document.modelContext;if(!context?.registerTool)return;context.registerTool({name:'aguatwin_compare_well_hypothesis',description:'Comparar os cinco modelos treinados em dados SIAGAS da Paraíba em um cenário de coordenadas e profundidade. Retorna hipóteses exploratórias, não confirmação de água.',inputSchema:{type:'object',properties:{latitude:{type:'number'},longitude:{type:'number'},depth_m:{type:'number'},task:{type:'string',enum:['potential','salinity']}},required:['latitude','longitude','depth_m'],additionalProperties:false},execute:async(args)=>{const selected=args.task||state.task;if(!['potential','salinity'].includes(selected))throw Error('Pergunta desconhecida.');const t=state.bundle.tasks[selected],x=[args.latitude,args.longitude,args.depth_m];if(!x.every(Number.isFinite))throw Error('Valores inválidos.');validatePoint(t,x);state.task=selected;ui('aiTask').value=selected;state.selectedId=null;ui('aiLat').value=args.latitude;ui('aiLon').value=args.longitude;ui('aiDepth').value=args.depth_m;comparison();const result=predict(x);return {content:[{type:'text',text:JSON.stringify(result)}]};}});}
async function init(){try{const [response,boundary]=await Promise.all([fetch('ai_models.json'),fetch('paraiba_boundary.json').then(r=>r.ok?r.json():null).catch(()=>null)]);if(!response.ok)throw Error('Não foi possível carregar os modelos.');state.bundle=await response.json();state.boundary=boundary;ui('aiTask').addEventListener('change',()=>{state.task=ui('aiTask').value;comparison();loadMunicipalities();});ui('aiMunicipality').addEventListener('change',loadWells);ui('aiWell').addEventListener('change',selectWell);for(const id of ['aiLat','aiLon','aiDepth'])ui(id).addEventListener('input',()=>{state.selectedId=null;ui('aiRecordNote').textContent='Entradas alteradas. Use “Comparar as IAs” para atualizar o resultado.';});ui('aiPredict').addEventListener('click',()=>{try{const r=state.selectedId?task().records.find(a=>a.id===state.selectedId):null;predict(inputs(),r);}catch(e){message(e.message,true);ui('aiPrediction').innerHTML='<tr><td>Estimativa indisponível: '+safe(e.message)+'</td></tr>';}});ui('aiCandidates').addEventListener('click',()=>{try{candidates();}catch(e){message(e.message,true);}});ui('aiNASA').addEventListener('click',()=>fetchNASA().catch(()=>{}));ui('nasaLiveExport').addEventListener('click',()=>{if(state.nasaRaw)download('NASA_POWER_ponto_consultado.json',JSON.stringify(state.nasaRaw,null,2),'application/json');});ui('nasaRestore').addEventListener('click',()=>{window.AguaTwin.restoreClimate();state.nasaRaw=null;ui('nasaLiveExport').disabled=true;ui('nasaLiveMessage').className='small';ui('nasaLiveMessage').textContent='Clima inicial restaurado: Cabaceiras, −7,49°, −36,29°, 2024–2025.';});ui('exportCandidates').addEventListener('click',()=>{if(!state.candidates.length)return;const cols=Object.keys(state.candidates[0]);download('AguaTwin_hipoteses_nao_confirmadas.csv',cols.join(',')+'\n'+state.candidates.map(a=>cols.map(k=>a[k]).join(',')).join('\n'),'text/csv');});for(const id of ['aiPredict','aiCandidates','aiNASA'])ui(id).disabled=false;comparison();loadMunicipalities();attachWebMCP();window.dispatchEvent(new Event('aguatwin-ready'));}catch(e){message(e.message,true);}}
 window.addEventListener('resize',()=>{if(ui('ai').classList.contains('active'))drawBenchmark();});document.querySelector('[data-tab="ai"]').addEventListener('click',()=>{if(state.bundle)drawBenchmark();});
 window.AguaTwinAI={state,infer,validatePoint,predict,candidates,parseNASA,fetchNASA,inputs,insideBoundary,ready:init()};
})();
